# @param {"type": "text", "default": "Which products are best for sensitive skin?", "placeholder": "ask the knowledge base...", "label": "KB query"}
kb_query = "Which products are best for sensitive skin?"

# Semantic search → top matching chunks with scores.
try:
    chunks = read_bedrock_kb(kb_query)
    print(f"Retrieved {len(chunks)} chunks for: {kb_query!r}")
    display(chunks[['score', 'source_uri', 'text']].head())
except Exception as e:
    print(f"No Knowledge Base available — skipping. ({type(e).__name__})")

# ask_bedrock_kb → a synthesized, cited answer grounded in the retrieved chunks.
try:
    result = ask_bedrock_kb(kb_query)
    print("ANSWER:\n" + result['answer'])
    print(f"\nGrounded in {len(result['citations'])} citation(s):")
    for c in result['citations'][:3]:
        print(f"  • {c.get('source_uri', '(no uri)')}")
except Exception as e:
    print(f"No Knowledge Base available — skipping. ({type(e).__name__})")

